pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value, bytes memory data) public {
        // Ensure target is not the zero address to avoid trivial failures
        vm.assume(target != address(0));
        // Bound value to a reasonable range
        value = bound(value, 0, 100 ether);

        // Record the contract's balance before the call
        uint256 balanceBefore = address(c).balance;

        // If target is the contract itself and value > 0, the call should revert
        // because the contract's fallback increments depositsCount, but the buggy contract
        // uses call instead of transfer, allowing reentrancy but the reference contract
        // uses transfer which forwards exactly 2300 gas and reverts on non-payable recipient.
        bool reverted = false;
        try c.sendMoney(target, value, data) {
            // If it didn't revert, check that the contract's balance didn't change
            // (the reference contract's transfer of ether to itself should fail, but if it succeeded, balance unchanged)
        } catch {
            reverted = true;
        }

        uint256 balanceAfter = address(c).balance;

        // General rule: if target == address(c) && value > 0, the call must revert
        // (because transfer to self reverts in the reference, but call succeeds in the mutant)
        if (target == address(c) && value > 0) {
            assertTrue(reverted, "sendMoney to self with value should revert");
        } else {
            // Otherwise the contract's balance should remain unchanged
            assertTrue(balanceAfter == balanceBefore, "sendMoney should not change contract balance");
        }
    }
}

